<?php
namespace App\Livewire\Admin\WhatsApp;use App\Models\WhatsAppConversation;use Livewire\Attributes\Url;use Livewire\Component;use Livewire\WithPagination;
class Index extends Component{use WithPagination;#[Url]public string $search='';#[Url]public string $scope='mine';#[Url]public ?int $folder=null;public function mount():void{abort_unless(auth()->user()->isAdmin()||auth()->user()->isSales(),403);}public function render(){$u=auth()->user();$q=WhatsAppConversation::query()->with(['contact','lead','assignedUser','folder'])->when(!$u->isAdmin()||$this->scope==='mine',fn($q)=>$q->where('assigned_to',$u->id))->when($u->isAdmin()&&$this->scope==='unassigned',fn($q)=>$q->whereNull('assigned_to'))->when($this->folder,fn($q)=>$q->where('folder_id',$this->folder))->when($this->search,fn($q)=>$q->whereHas('contact',fn($q)=>$q->where('profile_name','like','%'.$this->search.'%')->orWhere('phone','like','%'.$this->search.'%')));return view('livewire.admin.whatsapp.index',['conversations'=>$q->orderByRecentActivity()->paginate(30),'folders'=>$u->whatsappChatFolders()->orderBy('position')->get()])->layout('components.layouts.admin',['title'=>'WhatsApp inbox']);}}
